package android.text;import android.graphics.Canvas;import dev.mixer.android.ConcreteHostProbe;public class Layout {public static final int BREAK_STRATEGY_HIGH_QUALITY=1,HYPHENATION_FREQUENCY_NORMAL=2;private final int lines,height,baseline;private final float[] widths;public Layout(CharSequence text,float textSize,int width,int maximumLines){float glyph=Math.max(1,textSize*.5f);int capacity=Math.max(1,(int)(Math.max(1,width)/glyph));String[] paragraphs=text.toString().split("\n",-1);java.util.List<Float> measured=new java.util.ArrayList<>();for(String paragraph:paragraphs){int length=paragraph.codePointCount(0,paragraph.length());int rows=Math.max(1,(length+capacity-1)/capacity);for(int row=0;row<rows&&measured.size()<maximumLines;row++)measured.add(Math.min(capacity,Math.max(0,length-row*capacity))*glyph);}lines=Math.max(1,measured.size());baseline=Math.max(1,(int)Math.ceil(textSize*.8));height=lines*Math.max(1,(int)Math.ceil(textSize*1.2));widths=new float[lines];for(int i=0;i<measured.size();i++)widths[i]=measured.get(i);}public int getHeight(){return height;}public int getLineCount(){return lines;}public int getLineBaseline(int line){return baseline+line*height/lines;}public float getLineWidth(int line){return widths[line];}public void draw(Canvas canvas){ConcreteHostProbe.hit("Layout.draw","entry",this);ConcreteHostProbe.hit("Layout.draw","beforeReturn",this);}}
